import {loopBank} from './loop-model.js';
import {dialogueQuestion,dialogueIntents,createDialogue,submitDialogue,MAX_QUESTION_LENGTH} from './dialogue-model.js';
import {createLocalVoice} from './voice-local.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function parseDialogueRoute(key){const m=/^dialogue\/(math|chinese|english)\/([0-2])$/.exec(key);return m?`loop:${m[1]}:${m[2]}`:null;}
export function dialogueMarkup(questionId){const q=dialogueQuestion(questionId);if(!q)throw Error('Unsupported example');return `<div class="learning-workspace dialogue-workspace"><div class="workspace-heading"><a class="back" href="#">← 选科首页</a><div><h1>围绕这道题聊一聊</h1><p>本地模拟 · DeepSeek 未接通</p></div></div><div class="workspace-grid"><section class="question-card work-question"><div class="question-content"><label class="dialogue-label" for="dialogue-question">选择原创示例题</label><select id="dialogue-question">${Object.entries(loopBank).flatMap(([subject,bank])=>bank.items.map((_,i)=>`<option value="${subject}/${i}" ${questionId===`loop:${subject}:${i}`?'selected':''}>${bank.label} · 示例 ${i+1}</option>`)).join('')}</select><h2 class="question-title" tabindex="-1">${esc(q.question)}</h2><p class="muted">只围绕这道固定示例题。这里不评分、不修改练习记录，也不能判断自由输入的完整解题过程。</p><p class="dialogue-boundary">不要输入姓名、学校、密钥或个人资料。文字与转录只留在此页；切换题目、档案、离开或刷新后清空。</p></div><div class="question-actions dialogue-shortcuts" role="group" aria-label="快捷追问">${Object.entries(dialogueIntents).map(([key,label])=>`<button type="button" class="secondary" data-dialogue-intent="${key}">${label}</button>`).join('')}</div></section><section class="guide-pane dialogue-chat" aria-label="本地题目对话"><div class="dialogue-toolbar"><span>本页短期对话</span><button type="button" class="text-button" id="dialogue-clear">清空这页对话</button></div><div id="dialogue-log" class="dialogue-log" role="log" aria-live="polite" aria-relevant="additions text"><p class="dialogue-empty">点一个快捷问题开始。回答来自固定规则，不是真实模型。</p></div><form id="dialogue-form" class="dialogue-composer"><label class="dialogue-label" for="dialogue-input">打字或检查语音转录</label><textarea id="dialogue-input" maxlength="${MAX_QUESTION_LENGTH}" rows="2" placeholder="例如：给我一个提示" autocomplete="off" spellcheck="false" aria-describedby="dialogue-input-note"></textarea><p id="dialogue-input-note" class="dialogue-small">最多 160 字 · 点击发送也只在本页处理 · 最近 6 轮短期显示</p><div class="dialogue-buttons"><button class="primary" type="submit">发送到本地示例</button><button class="secondary" type="button" id="dialogue-mic" disabled>开始本机语音</button></div><div class="dialogue-buttons"><button class="secondary" type="button" id="dialogue-read" disabled>朗读最新回答</button><button class="text-button" type="button" id="dialogue-stop" aria-keyshortcuts="Escape" title="也可按 Esc 停止语音" disabled>停止语音</button></div><p id="dialogue-voice-capability" class="dialogue-small">正在检查本机语音能力…</p><p id="dialogue-status" class="dialogue-small" role="status" aria-live="polite"></p></form></section></div><p class="workspace-note">不保存对话或录音 · 无服务商请求 · 转到后台会停止语音，返回不自动重启 · 语音依赖浏览器本地能力</p></div>`;}
export function mountDialogue(main,questionId,{scope=globalThis,voiceFactory=createLocalVoice}={}){
 const state=createDialogue(questionId),field=main.querySelector('#dialogue-input'),log=main.querySelector('#dialogue-log'),form=main.querySelector('#dialogue-form'),mic=main.querySelector('#dialogue-mic'),read=main.querySelector('#dialogue-read'),stop=main.querySelector('#dialogue-stop'),status=main.querySelector('#dialogue-status'),capability=main.querySelector('#dialogue-voice-capability'),selector=main.querySelector('#dialogue-question');let disposed=false,controller;
 function updateVoice(s){if(disposed)return;mic.disabled=s.recognition!=='available'||s.listening;mic.textContent=s.listening?'正在本机识别…':'开始本机语音';read.disabled=!s.canRead||!state.lastAnswer||s.reading;stop.disabled=!s.listening&&!s.reading;capability.textContent=s.recognitionReason+' '+s.readReason;status.textContent=s.notice;}
 controller=voiceFactory({scope,onState:updateVoice,onTranscript:text=>{if(disposed)return;field.value=text;field.focus({preventScroll:true});}});
 function clear(){if(disposed)return;controller.stop();state.messages=[];state.lastAnswer='';state.revision++;field.value='';log.innerHTML='<p class="dialogue-empty">已清空。点一个快捷问题重新开始，仍是本地固定规则。</p>';updateVoice(controller.getState());status.textContent='本页对话和输入已清空，语音已停止；学习记录没有改变。';field.focus({preventScroll:true});}
 function send(text,intent){if(disposed)return;controller.stop();const response=submitDialogue(state,{text,intent});if(!response.ok){status.textContent='请输入 1 到 160 个字符，或点快捷问题。';return;}log.innerHTML=state.messages.map(m=>`<article class="dialogue-message ${m.role}"><strong>${m.role==='user'?'你':'本地示例'}</strong><p>${esc(m.text)}</p></article>`).join('');log.scrollTop=log.scrollHeight;field.value='';updateVoice(controller.getState());status.textContent='已在本页处理，没有发送给 DeepSeek 或其他服务商。';}
 const onSubmit=event=>{event.preventDefault();send(field.value);};
 const onClick=event=>{const b=event.target.closest('button');if(!b||b.disabled)return;const intent=b.dataset.dialogueIntent;if(intent&&Object.hasOwn(dialogueIntents,intent)){send(dialogueIntents[intent],intent);return;}if(b.id==='dialogue-clear'){clear();return;}if(b.id==='dialogue-mic')controller.startRecognition();if(b.id==='dialogue-read')controller.read(state.lastAnswer);if(b.id==='dialogue-stop')controller.stop();};
 const onKey=event=>{if(disposed||event.key!=='Escape')return;const current=controller.getState();if(current.listening||current.reading){event.preventDefault();controller.stop();status.textContent='语音已停止，当前对话和输入保留。';}};
 const onChange=()=>{if(disposed)return;scope.location.hash='dialogue/'+selector.value;};
 form.addEventListener('submit',onSubmit);main.addEventListener('click',onClick);main.addEventListener('keydown',onKey);selector.addEventListener('change',onChange);controller.probe();
 return ()=>{if(disposed)return;disposed=true;controller.dispose();form.removeEventListener('submit',onSubmit);main.removeEventListener('click',onClick);main.removeEventListener('keydown',onKey);selector.removeEventListener('change',onChange);state.messages=[];state.lastAnswer='';field.value='';};
}
